ion_status":"verified","last_verified_at":"2026-10-15","value_boolean":null,"value_text":"Free donor-funded public access with registration; donations are optional. Separate paid courses, workplace or research agreements are outside this edition.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"healthy-minds-program"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-15","value_boolean":null,"value_text":"A structured Awareness, Connection, Insight and Purpose program rather than the complete Calm catalog. Registration is required. Older offline instructions and conflicting documented iOS requirements remain limitations; the Android sample does not resolve them.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"medito"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"no-subscription"}}},"confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-15","value_boolean":true,"value_text":null,"value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"medito"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"pricing-model"}}},"confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-15","value_boolean":null,"value_text":"Free public app and meditation content, supported by donations; no paid perpetual license is implied.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"medito"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-15","value_boolean":null,"value_text":"A course-based meditation alternative rather than the complete Calm catalog. Core no-account access is vendor-documented but the owner tested signed in. App code licensing does not grant unrestricted reuse of original or partner audio.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"smiling-mind"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"no-subscription"}}},"confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-15","value_boolean":true,"value_text":null,"value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"smiling-mind"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"pricing-model"}}},"confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-15","value_boolean":null,"value_text":"Currently free individual access supported by the nonprofit; a registered account is required. This is not a perpetual-access guarantee.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"smiling-mind"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-15","value_boolean":null,"value_text":"A broader mental-fitness app with adult, family and other sections; the comparison covers adult guided sessions only. Account registration is required. Download features are documented but offline playback was not tested.","value_number":null,"value_enum":null}]},{"table":"product_anchors","operation":"upsert","conflictColumns":["product_id","anchor_id","relationship_type"],"rows":[{"product_id":{"$ref":{"table":"products","where":{"slug":"healthy-minds-program"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"calm"}}},"relationship_type":"alternative","confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-15","relationship_scope":"personal-adult-guided-meditation-selection-playback","scope_description":"For personal adult guided meditation, the Healthy Minds public program lets you choose and play a guided practice, as observed with Intro To Sitting Meditation. This substitutes for Calm guided-session selection and playback within a structured learning program, not for every Calm content category."},{"product_id":{"$ref":{"table":"products","where":{"slug":"medito"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"calm"}}},"relationship_type":"alternative","confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-15","relationship_scope":"personal-adult-guided-meditation-selection-playback","scope_description":"For personal adult guided meditation, Medito lets you choose a session from its courses and play guided audio, as observed with Learning to sit. This substitutes for selecting and playing a Calm guided meditation; it does not establish equivalent catalog, sleep stories or health outcomes."},{"product_id":{"$ref":{"table":"products","where":{"slug":"smiling-mind"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"calm"}}},"relationship_type":"alternative","confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-15","relationship_scope":"personal-adult-guided-meditation-selection-playback","scope_description":"For personal adult guided meditation, Smiling Mind lets you select an adult session and play guided audio, as observed with Exploring the Breath. This substitutes for the corresponding Calm selection/playback activity, without implying parity with Calm sleep stories, music or its entire catalog."}]},{"table":"claim_evidence","operation":"upsert","conflictColumns":["seed_key"],"rows":[{"seed_key":"seed-claim:01e8e00217112707c6f4ce4f76a27b1df664dd7970e6a36a2730ea51f02ead20","evidence_source_id":{"$ref":{"table":"evidence_sources","where":{"seed_key":"meditation-m2-2026-10-15"}}},"excerpt":null,"notes":"Seed source reference for [\"medito\",\"attributes\",\"pricing-model\"]. Source content is not embedded; this pointer is not an independently verified qu